#include "gemm.cuh"
#include <cuda_runtime.h>

static constexpr int TILE = 16;

__shared__ float As[TILE][TILE + 1];   // 1-col padding for bank conflict avoidance
__shared__ float Bs[TILE + 1][TILE];   // 1-row padding for bank conflict avoidance

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    const int row = blockIdx.y * TILE + threadIdx.y;
    const int col = blockIdx.x * TILE + threadIdx.x;
    const int numTiles = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        int aCol = t * TILE + threadIdx.x;
        int bRow = t * TILE + threadIdx.y;

        As[threadIdx.y][threadIdx.x] =
            (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
        Bs[threadIdx.y][threadIdx.x] =
            (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;
        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k)
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + TILE - 1) / TILE;
    int gy = (N + TILE - 1) / TILE;
    gemmKernel<<<gx, gy>>>(dA, dB, dC, N);
}

