#include "gemm.cuh"

#include <cuda_runtime.h>

// Block: 16x16 threads, each thread computes 2x2 output elements
#define BX 16
#define BY 16
#define RM 2  // output rows per thread
#define RN 2  // output cols per thread
#define K 16  // K tile

static const int OM = BY * RM;  // 32 output rows per block
static const int ON = BX * RN;  // 32 output cols per block

__shared__ float As[K][K];
__shared__ float Bs[K][K];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    // This thread handles 2 output elements: (r0,c0) and (r1,c1)
    const int r0 = br + threadIdx.y;
    const int r1 = r0 + BY;
    const int c0 = bc + threadIdx.x * RN;
    const int c1 = c0 + RN - 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    // Load first shared tile before loop
    As[threadIdx.y][threadIdx.x] =
        (r0 < N && threadIdx.x < N) ? A[r0 * N + threadIdx.x] : 0.0f;
    As[threadIdx.y + BY][threadIdx.x] =
        (r1 < N && threadIdx.x < N) ? A[r1 * N + threadIdx.x] : 0.0f;
    Bs[threadIdx.y][threadIdx.x] =
        (threadIdx.y < N && c0 < N) ? B[threadIdx.y * N + c0] : 0.0f;
    Bs[threadIdx.y][threadIdx.x] =
        (threadIdx.y < N && c1 < N) ? B[threadIdx.y * N + c1] : 0.0f;
    __syncthreads();

    for (int t = 0; t < nt; ++t) {
        // Compute
        #pragma unroll 16
        for (int k = 0; k < K; ++k) {
            register float ar0 = As[threadIdx.y][k];
            register float ar1 = As[threadIdx.y + BY][k];
            s00 += ar0 * Bs[k][threadIdx.x];
            s01 += ar0 * Bs[k][threadIdx.x];
            s10 += ar1 * Bs[k][threadIdx.x];
            s11 += ar1 * Bs[k][threadIdx.x];
        }

        // Load next tile
        if (t + 1 < nt) {
            int kNext = (t + 1) * K;
            As[threadIdx.y][threadIdx.x] =
                (r0 < N && kNext + threadIdx.x < N) ? A[r0 * N + kNext + threadIdx.x] : 0.0f;
            As[threadIdx.y + BY][threadIdx.x] =
                (r1 < N && kNext + threadIdx.x < N) ? A[r1 * N + kNext + threadIdx.x] : 0.0f;
            Bs[threadIdx.y][threadIdx.x] =
                (kNext + threadIdx.y < N && c0 < N) ? B[(kNext + threadIdx.y) * N + c0] : 0.0f;
            Bs[threadIdx.y][threadIdx.x] =
                (kNext + threadIdx.y < N && c1 < N) ? B[(kNext + threadIdx.y) * N + c1] : 0.0f;
            __syncthreads();
        }
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
    if (r1 < N && c1 < N) C[r1 * N + c1] = s11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + ON - 1) / ON;
    int gy = (N + OM - 1) / OM;
    gemmKernel<<<gx, gy>>>(dA, dB, dC, N);
}

