#include "gemm.cuh"

#include <cuda_runtime.h>

// 32x32 block, K=32: each thread handles 1 output element.
// Output tile: 32x32 per block. Shared memory: As[32][32], Bs[32][32].

#define K 32

__shared__ float As[K][K];
__shared__ float Bs[K][K];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int row = blockIdx.y * K + threadIdx.y;
    const int col = blockIdx.x * K + threadIdx.x;
    const int nt = (N + K - 1) / K;

    float acc = 0.0f;

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;
        int aCol = kOff + threadIdx.x;
        int bRow = kOff + threadIdx.y;

        As[threadIdx.y][threadIdx.x] =
            (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
        Bs[threadIdx.y][threadIdx.x] =
            (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;
        __syncthreads();

        #pragma unroll 32
        for (int k = 0; k < K; ++k)
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + K - 1) / K;
    int gy = (N + K - 1) / K;
    dim3 block(K, K);
    dim3 grid(gx, gy);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

