#include "gemm.cuh"

#include <cuda_runtime.h>

#define TILE 16

__shared__ float As[TILE][TILE + 1];  // 1-col padding avoids bank conflict
__shared__ float Bs[TILE + 1][TILE];  // 1-row padding avoids bank conflict

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int row = blockIdx.y * TILE + threadIdx.y;
    const int col = blockIdx.x * TILE + threadIdx.x;
    const int nt = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    // Pipelined: load tile 0 before loop, then compute & load next tile
    int aCol = threadIdx.x;
    int bRow = threadIdx.y;
    As[threadIdx.y][threadIdx.x] =
        (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
    Bs[threadIdx.y][threadIdx.x] =
        (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;
    __syncthreads();

    for (int t = 0; t < nt; ++t) {
        #pragma unroll 16
        for (int k = 0; k < TILE; ++k)
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];

        if (t + 1 < nt) {
            aCol = (t + 1) * TILE + threadIdx.x;
            bRow = (t + 1) * TILE + threadIdx.y;
            As[threadIdx.y][threadIdx.x] =
                (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
            Bs[threadIdx.y][threadIdx.x] =
                (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;
            __syncthreads();
        }
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + TILE - 1) / TILE;
    int gy = (N + TILE - 1) / TILE;
    dim3 block(TILE, TILE);
    dim3 grid(gx, gy);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

