    const int ty = threadIdx.y;   // 0..31
    const int tx = threadIdx.x;   // 0..7

    // This thread computes 4 output elements (4 columns) for row (br+ty)
    const int r = br + ty;
    const int c0 = bc + tx * 4;
    const int c1 = bc + tx * 4 + 1;
    const int c2 = bc + tx * 4 + 2;
    const int c3 = bc + tx * 4 + 3;

    float s0 = 0.0f, s1 = 0.0f, s2 = 0.0f, s3 = 0.0f;

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;

