#include "gemm.cuh"

#include <cuda_runtime.h>

// Tensor Core GEMM using __mma_sync on sm_86
// Block: 4 warps (128 threads), each warp computes 16x16 tile of C
// Shared memory: As[16][16], Bs[16][16] per warp, with async copies
// K=16, pipelined: overlap load of tile t+1 with compute of tile t

#define K 16
#define OM 16
#define ON 16

__shared__ float As[OM][K];
__shared__ float Bs[K][ON];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int warp = threadIdx.y;  // 0..3 (4 warps)
    const int lane = threadIdx.x;  // 0..31

    // Each warp handles OMxON = 16x16 output elements
    // Warp 0: rows br..br+15, cols bc..bc+15
    // Wait, with 4 warps per block and 16x16 output, each warp handles 16x4
    // Actually: warp 0-3 all in one block. Block handles 16x16.
    // 4 warps * 32 threads = 128 threads for 256 elements => 2 elements per thread

    // Warp 0: rows br..br+15, cols bc..bc+15 (128 elements, each thread handles 4)
    // No wait, we have 16x16=256 elements and 128 threads, so each thread does 2 elements

    const int warpRow = warp / 2;    // 0 or 1
    const int warpCol = warp % 2;    // 0 or 1

    // Warp 0,0: top-left quadrant: rows 0-7, cols 0-3
    // Warp 0,1: top-right quadrant: rows 0-7, cols 4-7
    // Warp 1,0: bottom-left quadrant: rows 8-15, cols 0-3
    // Warp 1,1: bottom-right quadrant: rows 8-15, cols 4-7
    // Actually this doesn't work cleanly. Let me use warp 0-3 differently.

    // Let's use a simpler approach: warp 0-3 each handle a different 16x4 quadrant
    // Warp 0: rows 0-15, cols 0-3
    // Warp 1: rows 0-15, cols 4-7
    // Warp 2: rows 8-15, cols 0-3
